-- Isolated owner accounting fixtures; safe to run on hosted Supabase with rollback.
begin;
create temp table finance_ids(key text primary key,id uuid);
insert into finance_ids values('owner','b81f0000-0000-4000-8000-000000000001'),('other','b81f0000-0000-4000-8000-000000000002'),('staff','b81f0000-0000-4000-8000-000000000003'),('customer','b81f0000-0000-4000-8000-000000000004');
insert into auth.users(id,email)select id,key||'-finance-fixture@example.invalid'from finance_ids;
insert into finance_ids select k,gen_random_uuid()from unnest(array['salon','salon2','foreign','chair','chair2','foreignchair','expense','unpaid','capital','request1','request2','request3','request4','request5','request6','request7','request8'])k;
create function pg_temp.i(k text)returns uuid language sql stable as $$select id from pg_temp.finance_ids where key=k$$;
create function pg_temp.today()returns date language sql stable as $$select(now()at time zone'Asia/Colombo')::date$$;
create function pg_temp.at(day_offset int,tm time default'12:00')returns timestamptz language sql stable as $$select(pg_temp.today()+day_offset+tm)at time zone'Asia/Colombo'$$;
create function pg_temp.ok(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;end;$$;
create function pg_temp.denied(statement text,expected text default'42501')returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=expected then return;end if;raise exception 'Expected %, got %: %',expected,sqlstate,sqlerrm;end;raise exception 'Unauthorized operation succeeded: %',statement;end;$$;
create function pg_temp.filters(s uuid default null)returns jsonb language sql stable as $$select jsonb_build_object('salon_id',s,'from',pg_temp.today(),'to',pg_temp.today())$$;
create function pg_temp.expense_data(k text,request text,ver int,amount int,status text default'expected',kind text default'operating',reason text default'')returns jsonb language sql stable as $$select jsonb_build_object('id',pg_temp.i(k),'request_id',pg_temp.i(request),'salon_id',pg_temp.i('salon'),'version',ver,'description','Fixture cost','category_code','rent','amount_minor',amount,'kind',kind,'status',status,'due_on',pg_temp.today(),'paid_on',pg_temp.today(),'change_reason',reason)$$;
do $$begin execute format('grant usage on schema %I to authenticated,anon',pg_my_temp_schema()::regnamespace);end;$$;
grant all on finance_ids to authenticated;
grant select on finance_ids to anon;
set local role anon;
select pg_temp.denied($q$select public.owner_finance('report','{}')$q$);
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i('owner'))::text,true);
set local role authenticated;
select public.manager_command('create_salon',jsonb_build_object('id',pg_temp.i('salon'),'name','Finance fixture one','address','Akurana','opens_at','00:00','closes_at','23:59','weekdays','[0,1,2,3,4,5,6]'::jsonb));
select public.manager_command('create_salon',jsonb_build_object('id',pg_temp.i('salon2'),'name','Finance fixture two','address','Akurana','opens_at','00:00','closes_at','23:59','weekdays','[0,1,2,3,4,5,6]'::jsonb));
select public.manager_command('create_barber',jsonb_build_object('id',pg_temp.i('chair'),'salon_id',pg_temp.i('salon'),'display_name','Finance chair'));
select public.manager_command('create_barber',jsonb_build_object('id',pg_temp.i('chair2'),'salon_id',pg_temp.i('salon2'),'display_name','Second chair'));
select pg_temp.ok((public.owner_finance('report',pg_temp.filters())->'summary'->>'revenue_minor')::bigint=0,'Empty business has real zero revenue');
select pg_temp.ok(exists(select 1 from jsonb_array_elements(public.owner_finance('report',pg_temp.filters())->'categories')c where c->>'code'='rent'),'Database expense categories are available after a clean development reset');
select pg_temp.denied($q$select public.owner_finance('report',jsonb_build_object('from',pg_temp.today()-400,'to',pg_temp.today()))$q$,'P0001');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i('other'))::text,true);
select public.manager_command('create_salon',jsonb_build_object('id',pg_temp.i('foreign'),'name','Foreign finance fixture','address','Akurana','opens_at','00:00','closes_at','23:59','weekdays','[0,1,2,3,4,5,6]'::jsonb));
select public.manager_command('create_barber',jsonb_build_object('id',pg_temp.i('foreignchair'),'salon_id',pg_temp.i('foreign'),'display_name','Foreign chair'));
reset role;
insert into bookmyturn_private.salon_memberships(salon_id,user_id,barber_id,role)values(pg_temp.i('salon'),pg_temp.i('staff'),pg_temp.i('chair'),'barber');
create function pg_temp.pin(s uuid,lat jsonb default'7.368',lng jsonb default'80.615')returns jsonb language sql stable as $$
select jsonb_build_object('salon_id',s,'name','Pinned salon','address','Akurana','latitude',lat,'longitude',lng,
'hours',(select jsonb_agg(jsonb_build_object('weekday',weekday,'opens_at',left(opens_at::text,5),'closes_at',left(closes_at::text,5)))from public.salon_hours where salon_id=s))$$;
create function pg_temp.create_pin(s uuid,lat jsonb default'7.368',lng jsonb default'80.615')returns jsonb language sql stable as $$
select jsonb_build_object('id',s,'name','Pinned new salon','address','Akurana','latitude',lat,'longitude',lng,'weekdays','[0,1,2,3,4,5,6]'::jsonb,'opens_at','09:00','closes_at','20:00')$$;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i('owner'))::text,true);
select public.manager_command('create_salon',pg_temp.create_pin(pg_temp.i('request1')));
select pg_temp.ok(exists(select 1 from jsonb_array_elements(public.manager_state()->'salons')s where(s->>'id')::uuid=pg_temp.i('request1')and(s->>'latitude')::numeric=7.368 and(s->>'longitude')::numeric=80.615),'Create pin persisted and returned to owner');
select public.manager_command('create_salon',pg_temp.create_pin(pg_temp.i('request1'),'8','81'));
select pg_temp.ok((select latitude=7.368 from public.salons where id=pg_temp.i('request1')),'Create retry cannot move existing pin');
select public.manager_command('salon',pg_temp.pin(pg_temp.i('salon')));
select pg_temp.ok((select latitude=7.368 and longitude=80.615 from public.salons where id=pg_temp.i('salon')),'Edit a legacy salon adds pin');
select public.manager_command('salon',pg_temp.pin(pg_temp.i('salon'),'0','0'));
select pg_temp.ok((select latitude=0 and longitude=0 from public.salons where id=pg_temp.i('salon')),'Zero coordinates are valid');
select public.manager_command('salon',pg_temp.pin(pg_temp.i('salon'),'90','-180'));
select pg_temp.ok((select latitude=90 and longitude=-180 from public.salons where id=pg_temp.i('salon')),'Boundary coordinates are valid');
select pg_temp.denied($q$select public.manager_command('salon',pg_temp.pin(pg_temp.i('salon'),'91','80'))$q$,'P0001');
select pg_temp.denied($q$select public.manager_command('salon',pg_temp.pin(pg_temp.i('salon'),'7','181'))$q$,'P0001');
select pg_temp.denied($q$select public.manager_command('salon',pg_temp.pin(pg_temp.i('salon'),'"7"','80'))$q$,'P0001');
select pg_temp.denied($q$select public.manager_command('salon',pg_temp.pin(pg_temp.i('salon'),'null','null'))$q$,'P0001');
select pg_temp.denied($q$select public.manager_command('salon',pg_temp.pin(pg_temp.i('salon'))-'longitude')$q$,'P0001');
select pg_temp.denied($q$select public.manager_command('salon',pg_temp.pin(pg_temp.i('salon'))||jsonb_build_object('latitude','NaN'))$q$,'P0001');
select pg_temp.denied($q$select public.manager_command('create_salon',pg_temp.create_pin(pg_temp.i('request2'),'100','80'))$q$,'P0001');
select pg_temp.ok(not exists(select 1 from public.salons where id=pg_temp.i('request2')),'Invalid pin cannot partially create a salon');
select pg_temp.ok((select latitude=90 and longitude=-180 from public.salons where id=pg_temp.i('salon')),'Invalid edits do not partially update pin');
select pg_temp.denied($q$select public.manager_command('salon',pg_temp.pin(pg_temp.i('foreign')))$q$);
select pg_temp.denied($q$select public.manager_command('create_salon',pg_temp.create_pin(pg_temp.i('foreign')))$q$);
select public.manager_command('salon',pg_temp.pin(pg_temp.i('salon')));
-- Omitted coordinates preserve existing pins for earlier app versions.
select public.manager_command('salon',pg_temp.pin(pg_temp.i('salon'))-'latitude'-'longitude');
select pg_temp.ok((select latitude=7.368 from public.salons where id=pg_temp.i('salon')),'Legacy update preserves existing pin');
select public.manager_command('archive_salon',jsonb_build_object('salon_id',pg_temp.i('request1')));
select pg_temp.denied($q$select public.manager_command('salon',pg_temp.pin(pg_temp.i('request1')))$q$,'P0001');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i('staff'))::text,true);
select pg_temp.denied($q$select public.manager_command('salon',pg_temp.pin(pg_temp.i('salon')))$q$);
select pg_temp.denied($q$select bookmyturn_private.manager_location_command_v1('salon',pg_temp.pin(pg_temp.i('salon')))$q$);
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i('customer'))::text,true);
select pg_temp.denied($q$select public.manager_command('salon',pg_temp.pin(pg_temp.i('salon')))$q$);
reset role;
set local role anon;
select pg_temp.ok(exists(select 1 from jsonb_array_elements(public.customer_catalog()->'salons')s where(s->>'id')::uuid=pg_temp.i('salon')and(s->>'latitude')::numeric=7.368 and(s->>'longitude')::numeric=80.615),'Customers receive exact public pin');
select pg_temp.ok(exists(select 1 from jsonb_array_elements(public.customer_catalog()->'salons')s where(s->>'id')::uuid=pg_temp.i('salon2')and s->>'latitude' is null and s->>'longitude' is null),'Legacy pins remain null, not invented');
select pg_temp.denied($q$select public.manager_command('salon',pg_temp.pin(pg_temp.i('salon')))$q$);
select pg_temp.denied($q$update public.salons set latitude=9,longitude=81 where id=pg_temp.i('salon')$q$);
reset role;
select pg_temp.denied($q$update public.salons set longitude=null where id=pg_temp.i('salon')$q$,'23514');
select pg_temp.denied($q$update public.salons set latitude='NaN'::float8 where id=pg_temp.i('salon')$q$,'23514');
rollback;
